#!/usr/bin/env ruby
# frozen_string_literal: true

# Composes the ebook cover: fits the (label-free) cover art to 1600x2560
# (KDP's recommended ebook cover, 1:1.6), then sets title, subtitle and author
# as real type, so text is never generated by the image model. The layout lives
# in cover_layout.rb, shared with the printed wraparound (compose_kdp_cover.rb).
#
# Usage: scripts/compose_cover.rb ART OUT [--lang pt]
# Text comes from book/outline.yml (meta.working_title / subtitle / author).

require_relative "cover_layout"

art, out = ARGV[0], ARGV[1]
abort "usage: compose_cover.rb ART OUT" unless art && out
lang = ARGV.include?("--lang") ? ARGV[ARGV.index("--lang") + 1] : "pt"
ROOT = CoverLayout::ROOT
W, H = 1600, 2560

cmd = ["magick", art, "-resize", "#{W}x#{H}^", "-gravity", "center", "-extent", "#{W}x#{H}",
       *CoverLayout.front_layers(lang:, w: W, h: H),
       "-alpha", "remove", "-alpha", "off", "-colorspace", "sRGB", "-quality", "95", out]
system(*cmd, exception: true)
warn "wrote #{out}"

# The README shows both covers side by side: keep the thumbnails in step automatically.
readme_name = { "cover.png" => "cover-readme.jpg", "cover-en.png" => "cover-readme-en.jpg" }[File.basename(out)]
if readme_name
  readme = File.join(ROOT, "assets", "cover", readme_name)
  system("magick", out, "-resize", "640x", "-quality", "88", readme, exception: true)
  warn "wrote #{readme.delete_prefix(ROOT + '/')}"
end
